def _split_line_before_cursor(text: str) -> tuple[list[str], str]:
    """Split the text before the cursor into the complete words and the
    incomplete word, using the same rules as :func:`split_arg_string`.
    """
    if not text:
        return [], ""

    words = split_arg_string(text)

    # Trailing whitespace separates words only when it is not inside quotes or
    # escaped. Appending a character then starts a new word only in that case.
    if text[-1] in _LINE_WHITESPACE and (
        len(split_arg_string(f"{text}x")) == len(words) + 1
    ):
        return words, ""

    if not words:
        return [], ""

    return words[:-1], words[-1]


class LineComplete(ShellComplete):
    """Shell completion for Bash's ``complete -C`` protocol. The program is
    run with the command line in ``COMP_LINE`` and the cursor offset in
    ``COMP_POINT``, and writes one completion per line to stdout.

    .. versionadded:: 8.6.0
    """

    name: t.ClassVar[str] = "line"
    source_template: t.ClassVar[str] = _SOURCE_LINE

    def _read_line(self) -> tuple[list[str], str]:
        """Read the line and cursor position from the environment and split
        the text before the cursor. Returns the complete words, including
        the program name, and the incomplete word.
        """
        line = os.environ.get("COMP_LINE")

        if line is None:
            raise CompletionRequestError("COMP_LINE is not set.")

        raw_point = os.environ.get("COMP_POINT", "")

        if raw_point == "":
            point = len(line)
        else:
            if _LINE_POINT_RE.fullmatch(raw_point) is None:
                raise CompletionRequestError(
                    f"Invalid COMP_POINT value {raw_point!r}:"
                    " expected a non-negative integer."
                )

            point = int(raw_point)

            if point > len(line):
                unit = "character" if len(line) == 1 else "characters"
                raise CompletionRequestError(
                    f"COMP_POINT {point} is past the end of COMP_LINE"
                    f" ({len(line)} {unit})."
                )

        return _split_line_before_cursor(line[:point])

    def get_completion_args(self) -> tuple[list[str], str]:
        words, incomplete = self._read_line()
        return words[1:], incomplete

    def format_completion(self, item: CompletionItem[str]) -> str:
        return f"{item.value}\n"

    def complete(self) -> str:
        words, incomplete = self._read_line()

        # The first complete word is the program name, which is ignored.
        if not words:
            return ""

        out = []

        for item in self.get_completions(words[1:], incomplete):
            if item.type != "plain":
                continue

            value = str(item.value)

            if "\n" in value or "\r" in value:
                continue

            out.append(self.format_completion(item))

        return "".join(out)


